import pandas as pddef select_best_spectrum(input_csv, snr_column, output_file='best_spectrum.csv'):    """    Reads a CSV, identifies the best spectrum based on highest SNR,    and saves it to a new file.    """    try:        # 1. Load the master CSV file        df = pd.read_csv(input_csv)        print(f"Loaded {len(df)} spectra.")        # 2. Find the index of the row with the maximum SNR        # Ensure SNR column is numeric        df[snr_column] = pd.to_numeric(df[snr_column])        best_spectrum_idx = df[snr_column].idxmax()                best_spectrum = df.loc[[best_spectrum_idx]] # Using [[]] keeps it as a DataFrame        print(f"Best spectrum found with SNR: {best_spectrum[snr_column].values[0]}")        # 3. Save to a new CSV        best_spectrum.to_csv(output_file, index=False)        print(f"Best spectrum saved to {output_file}")    except Exception as e:        print(f"Error: {e}")        select_best_spectrum('Carmen_master_spectra.csv', 'SNR_General')# Example Usage:# Assuming 'master_spectra.csv' has a column 'SNR'# select_best_spectrum('master_spectra.csv', 'SNR')